python -c "
import numpy as np
L=[l.split() for l in open('opt1.xyz').read().split('\n')[2:] if l.strip()]
s=[x[0] for x in L]; c=np.array([[float(y) for y in x[1:]] for x in L])
n=len(s)
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Ru':1.46}
adj={i:[] for i in range(n)}
for i in range(n):
  for j in range(i+1,n):
    d=np.linalg.norm(c[i]-c[j])
    if d< (cov[s[i]]+cov[s[j]])*1.3: adj[i].append(j); adj[j].append(i)
for i in range(n):
  if s[i]!='H': print(i,s[i],[(j,s[j]) for j in adj[i]])
"
